using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "AstriumVesselOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/AstriumVesselOmenData")]
public class AstriumVesselOmenData : PlayerAndSentinelsExceededPurifyOmenData
{
	protected override void ExceededPurifyAction(int exceededPurifyAmount, OmenInstance omenInstance)
	{
		int num = counter + exceededPurifyAmount;
		int num2 = Mathf.FloorToInt((float)num / (float)TriggerAmount);
		for (int i = 0; i < num2; i++)
		{
			omenInstance.EnqueueOmenFeedbackAndPlay();
			ActivateOmenWithoutCounter();
		}
		counter = num - num2 * TriggerAmount;
		omenInstance.UpdateOmenCounter();
	}

	public override string OmenConvertedDescription()
	{
		string description = Smart.Format(GetPurifyReceiveThatExceedDescription(), GetOmenRawLocalizedDescription()) + "\n" + Smart.Format(base.localizationManager.GetLocalizedWhenThisCounterReaches(), TriggerAmount, GetOmenConvertedDescriptionBattleAction().LowercaseFirst());
		return CheckAppendCounterKeptBetweenBattlesDescription(description);
	}
}
